ctx.canvas.width = 960;
ctx.canvas.height = 540;
// 背景
ctx.fillStyle = 'rgba(255, 255, 255, 0)';
ctx.fillRect(0, 0, canvas_panel.width, canvas_panel.height);
const img = new Image();
let panel; // panelを外で定義しておく
img.onload = ()=>{
    ctx.drawImage(img, 0, 0);
    // テキスト描画
    ctx.fillStyle = 'lightblue';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = '100px sans-serif';
    ctx.fillText("\u671B\u9060\u93E1", 580, 170); // 中央寄りに
    // Canvas を Three.js のテクスチャに変換
    const texture_panel = new _three.CanvasTexture(canvas_panel);
    texture_panel.needsUpdate = true;
    // 平面ジオメトリ（縦横比をキャンバスと一致させると綺麗）
    const geometry_panel = new _three.PlaneGeometry(2, 1); // 縦横 = 2:1
    geometry_panel.translate(1, 0.5, 0);
    const material_panel = new _three.MeshBasicMaterial({
        map: texture_panel,
        transparent: true,
        opacity: 1.5,
        side: _three.DoubleSide,
        alphaTest: 0.1,
        depthWrite: false
    });
    panel = new _three.Mesh(geometry_panel, material_panel);
    // 表示位置を調整（カメラから見えるところに）
    panel.position.set(1, 3, 0);
    panel.rotation.y = -Math.PI / 2;
    panel.visible = false;
    scene.add(panel);
};
