//時間変更を記録する変数
let CT_year, CT_month, CT_day, CT_hour, CT_min, CT_sec;
function isValidDate(y, m, d) {
    const date = new Date(y, m - 1, d);
    return date.getFullYear() === y && date.getMonth() === m - 1 && date.getDate() === d;
}
function getMaxDay(year, month) {
    return new Date(year, month, 0).getDate(); //前月の末日
}
let mousedown_on_telescope = false;
canvas.addEventListener('mousedown', (event)=>{
    if (!at_main_content) {
        const element = event.currentTarget;
        //canvas上のマウスのXY座標
        const x = event.clientX - element.offsetLeft;
        const y = event.clientY - element.offsetTop;
        //canvasの幅と高さを取得
        const w = element.offsetWidth;
        const h = element.offsetHeight;
        //マウス座標を-1〜1の範囲に変換
        mouse.x = x / w * 2 - 1;
        mouse.y = -(y / h) * 2 + 1;
        // マウス位置からRayを発射
        scene.updateMatrixWorld(); // 必須: ワールド行列の更新
        raycaster.setFromCamera(mouse, camera);
        var allObjects;
        if (!changing_time && !moving_location && !transitioning) {
            allObjects = scene.children.filter((obj)=>obj !== panel && obj !== star_panel && obj !== star_panel_time); // panelを除外
            particle_list.forEach((particles)=>{
                allObjects = allObjects.filter((obj)=>obj !== particles);
            });
        } else allObjects = scene.children.filter((obj)=>obj === star_panel_time);
        if (changing_location_Q != 0) allObjects = [];
        // オブジェクトとの交差を検出
        const intersects = raycaster.intersectObjects(allObjects, true);
        console.log(intersects);
        const meshHits = intersects.filter((i)=>i.object.isMesh); //Points
        console.log(meshHits);
        // 交差したオブジェクトがあればイベントを発火
        if (meshHits.length > 0) {
            const object = meshHits[0].object;
            if (!changing_time) {
                let group = object;
                while(group.parent && !group.parent.name)group = group.parent;
                if (group.parent) group = group.parent;
                //console.log('クリックされたグループ:', group.name);
                if (group.name == "\u671B\u9060\u93E1") mousedown_on_telescope = true;
            } else {
                let simulatedDate = getSimulatedDate();
                simulatedDate = new Date(simulatedDate.getTime() + offsetHours * 3600000);
                let year = simulatedDate.getFullYear();
                let month = simulatedDate.getMonth() + 1;
                let day = simulatedDate.getDate();
                let hour = simulatedDate.getHours();
                let min = simulatedDate.getMinutes();
                console.log(meshHits[0].uv);
                const click_uv = meshHits[0].uv;
                for(let keyx in chTime_x_list){
                    console.log(keyx);
                    console.log(chTime_x_list[keyx]);
                    if (chTime_x_list[keyx][0] < click_uv.x && click_uv.x < chTime_x_list[keyx][1]) {
                        for(let keyy in chTime_y_list)if (chTime_y_list[keyy][0] > click_uv.y && click_uv.y > chTime_y_list[keyy][1]) {
                            if ("up1" == keyy) {
                                console.log(keyy);
                                if (keyx.includes("y")) {
                                    const digit = Number(keyx.replace("y", ""));
                                    console.log("digit:", digit);
                                    if (digit == 5) {
                                        if (CT_year >= 90000) CT_year -= 90000;
                                        else CT_year += 10000;
                                    } else if (digit == 4) {
                                        if (CT_year % 10000 >= 9000) CT_year -= 9000;
                                        else CT_year += 1000;
                                    } else if (digit == 3) {
                                        if (CT_year % 1000 >= 900) CT_year -= 900;
                                        else CT_year += 100;
                                    } else if (digit == 2) {
                                        if (CT_year % 100 >= 90) CT_year -= 90;
                                        else CT_year += 10;
                                    } else if (digit == 1) {
                                        if (CT_year % 10 >= 9) CT_year -= 9;
                                        else CT_year += 1;
                                    }
                                } else if (keyx.includes("m")) {
                                    let oldCT_month = CT_month;
                                    const digit = Number(keyx.replace("m", ""));
                                    if (digit == 2) {
                                        if (CT_month % 10 < 3) {
                                            if (CT_month >= 10) CT_month -= 10;
                                            else CT_month += 10;
                                        }
                                    } else {
                                        if (CT_month % 10 >= 9) CT_month -= 8;
                                        else CT_month += 1;
                                        if (CT_month % 10 >= 3 && CT_month >= 10) CT_month -= 10;
                                    }
                                    if (CT_month == 0) CT_month = oldCT_month;
                                    let Max_day = getMaxDay(CT_year, CT_month);
                                    if (Max_day < CT_day) CT_day = Max_day;
                                } else if (keyx.includes("d")) {
                                    const digit = Number(keyx.replace("d", ""));
                                    let old_CT_day = CT_day;
                                    if (digit == 2) {
                                        let m_Threshold;
                                        if (CT_month == 2) m_Threshold = 20;
                                        else m_Threshold = 30;
                                        if (CT_day >= m_Threshold) CT_day -= m_Threshold;
                                        else CT_day += 10;
                                    } else if (CT_day % 10 >= 9) CT_day -= 9;
                                    else CT_day += 1;
                                    if (!isValidDate(CT_year, CT_month, CT_day)) CT_day = old_CT_day;
                                }
                            }
                            if ("down1" == keyy) {
                                if (keyx.includes("y")) {
                                    const digit = Number(keyx.replace("y", ""));
                                    console.log("digit:", digit);
                                    if (digit == 5) {
                                        if (CT_year < 10000) CT_year += 90000;
                                        else CT_year -= 10000;
                                    } else if (digit == 4) {
                                        if (CT_year % 10000 < 1000) CT_year += 9000;
                                        else CT_year -= 1000;
                                    } else if (digit == 3) {
                                        if (CT_year % 1000 < 100) CT_year += 900;
                                        else CT_year -= 100;
                                    } else if (digit == 2) {
                                        if (CT_year % 100 < 10) CT_year += 90;
                                        else CT_year -= 10;
                                    } else if (digit == 1) {
                                        if (CT_year % 10 == 0) CT_year += 9;
                                        else CT_year -= 1;
                                    }
                                } else if (keyx.includes("m")) {
                                    let oldCT_month = CT_month;
                                    const digit = Number(keyx.replace("m", ""));
                                    if (digit == 2) {
                                        if (CT_month % 10 < 3) {
                                            if (CT_month < 10) CT_month += 10;
                                            else CT_month -= 10;
                                        }
                                    } else {
                                        if (CT_month % 10 == 1) CT_month += 8;
                                        else CT_month -= 1;
                                        if (CT_month % 10 >= 3 && CT_month >= 10) CT_month -= 10;
                                    }
                                    if (CT_month == 0) CT_month = oldCT_month;
                                    let Max_day = getMaxDay(CT_year, CT_month);
                                    if (Max_day < CT_day) CT_day = Max_day;
                                } else if (keyx.includes("d")) {
                                    const digit = Number(keyx.replace("d", ""));
                                    let old_CT_day = CT_day;
                                    if (digit == 2) {
                                        let m_Threshold;
                                        if (CT_month == 2) m_Threshold = 20;
                                        else m_Threshold = 30;
                                        if (CT_day < 10) CT_day += m_Threshold;
                                        else CT_day -= 10;
                                    } else if (CT_day % 10 == 0) CT_day += 9;
                                    else CT_day -= 1;
                                    if (!isValidDate(CT_year, CT_month, CT_day)) CT_day = old_CT_day;
                                }
                            }
                            if ("up2" == keyy) {
                                if (keyx.includes("h")) {
                                    const digit = Number(keyx.replace("h", ""));
                                    let old_CT_hour = CT_hour;
                                    if (digit == 2) {
                                        let max2;
                                        if (CT_hour % 10 > 3) max2 = 10;
                                        else max2 = 20;
                                        if (CT_hour >= max2) CT_hour -= max2;
                                        else CT_hour += 10;
                                    } else {
                                        if (CT_hour % 10 == 9) CT_hour -= 9;
                                        else CT_hour += 1;
                                        if (CT_hour % 10 >= 4 && CT_hour >= 20) CT_hour -= 20;
                                    }
                                    if (CT_hour >= 24) CT_hour = old_CT_hour;
                                }
                                if (keyx.includes("f")) {
                                    const digit = Number(keyx.replace("f", ""));
                                    if (digit == 2) {
                                        if (CT_min >= 50) CT_min -= 50;
                                        else CT_min += 10;
                                    } else if (CT_min % 10 == 9) CT_min -= 9;
                                    else CT_min += 1;
                                }
                            }
                            if ("down2" == keyy) {
                                if (keyx.includes("h")) {
                                    const digit = Number(keyx.replace("h", ""));
                                    if (digit == 2) {
                                        let max2;
                                        if (CT_hour % 10 > 3) max2 = 10;
                                        else max2 = 20;
                                        if (CT_hour < 10) CT_hour += max2;
                                        else CT_hour -= 10;
                                    } else {
                                        if (CT_hour % 10 == 0) CT_hour += 9;
                                        else CT_hour -= 1;
                                        if (CT_hour % 10 >= 4 && CT_hour >= 20) CT_hour -= 20;
                                    }
                                }
                                if (keyx.includes("f")) {
                                    const digit = Number(keyx.replace("f", ""));
                                    if (digit == 2) {
                                        if (CT_min < 10) CT_min += 50;
                                        else CT_min -= 10;
                                    } else if (CT_min % 10 == 0) CT_min += 9;
                                    else CT_min -= 1;
                                }
                            }
                            change_show_time(CT_year, CT_month, CT_day, CT_hour, CT_min);
                        }
                    }
                }
            }
        }
    }
});
