const size = 1536;
function get_6dir_img() {
    const faceImages = [];
    const gl = renderer.getContext();
    const originalPosition = camera.position.clone();
    const originalUp = camera.up.clone();
    const originalFov = camera.fov;
    const originalAspect = camera.aspect;
    const originalDirection = camera.getWorldDirection(new _three.Vector3()).clone();
    const originalLookAt = originalPosition.clone().add(originalDirection);
    const original_zoom = camera.zoom;
    camera.fov = 90;
    camera.aspect = 1;
    camera.zoom = 1;
    camera.updateProjectionMatrix();
    for (const dir of directions){
        // 新しいカメラを作成
        //const cam = new THREE.PerspectiveCamera(90, 1, 0.1, 10000);
        camera.position.set(0, 0, 0);
        camera.up.fromArray(dir.up);
        camera.lookAt(new _three.Vector3().fromArray(dir.lookAt));
        //camera.lookAt(lookAtVector);
        renderer.setSize(size / window.devicePixelRatio, size / window.devicePixelRatio);
        composer.setSize(size / window.devicePixelRatio, size / window.devicePixelRatio);
        //renderer.setSize(size, size, false); // 物理サイズとCSSサイズを一致させない
        renderer.domElement.style.width = `${size}px`;
        renderer.domElement.style.height = `${size}px`;
        // Composerのサイズをターゲットに合わせる
        // ピクセルデータを格納するための配列
        const pixels = new Uint8Array(size * size * 4); // RGBA
        // レンダーターゲットを指定
        //const framebuffer = gl.createFramebuffer();
        composer.render();
        const buffer = composer.readBuffer;
        gl.bindFramebuffer(gl.FRAMEBUFFER, buffer.__webglFramebuffer);
        //gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
        //renderer.render()
        gl.readPixels(0, 0, size, size, gl.RGBA, gl.UNSIGNED_BYTE, pixels);
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        // imageData を作成して読み取ったピクセルデータを設定
        const imageData = ctx.createImageData(size, size);
        canvas.dataset.name = dir.name;
        // ピクセルを上下反転してコピー
        for(let y = 0; y < size; y++)for(let x = 0; x < size; x++){
            const destIdx = (y * size + x) * 4;
            const srcIdx = ((size - y - 1) * size + x) * 4;
            imageData.data[destIdx] = pixels[srcIdx];
            imageData.data[destIdx + 1] = pixels[srcIdx + 1];
            imageData.data[destIdx + 2] = pixels[srcIdx + 2];
            imageData.data[destIdx + 3] = 255; // pixels[srcIdx + 3]; 透明度
        }
        ctx.putImageData(imageData, 0, 0);
        // 作成した画像をfaceImagesに追加
        //document.body.appendChild(canvas);
        faceImages.push(canvas);
    }
    const faceMap = {};
    for (const face of faceImages)faceMap[face.dataset.name] = face;
    renderer.setSize(width, height);
    composer.setSize(width, height);
    composer.render();
    camera.position.copy(originalPosition);
    camera.up.copy(originalUp);
    camera.fov = originalFov;
    camera.aspect = originalAspect;
    camera.lookAt(originalLookAt);
    camera.zoom = original_zoom;
    camera.updateProjectionMatrix();
    const outputCanvas = document.createElement('canvas');
    outputCanvas.width = size * 2;
    outputCanvas.height = size;
    const ctx = outputCanvas.getContext('2d');
    const outputImageData = ctx.createImageData(outputCanvas.width, outputCanvas.height);
    for(let y = 0; y < outputCanvas.height; y++)for(let x = 0; x < outputCanvas.width; x++){
        // 正距円筒におけるピクセルの方向ベクトルを計算
        const theta = x / outputCanvas.width * 2 * Math.PI - Math.PI;
        const phi = -(y / outputCanvas.height * Math.PI - 0.5 * Math.PI);
        const dir = new _three.Vector3(Math.cos(theta) * Math.cos(phi), Math.sin(phi), Math.sin(theta) * Math.cos(phi));
        const { face, u, v } = directionToCubeUV(dir);
        {
            const pixel = getPixelFromFace(faceMap[face], u, v, face);
            const idx = (y * outputCanvas.width + x) * 4;
            outputImageData.data[idx + 0] = pixel[0];
            outputImageData.data[idx + 1] = pixel[1];
            outputImageData.data[idx + 2] = pixel[2];
            outputImageData.data[idx + 3] = 255;
        }
    }
    ctx.putImageData(outputImageData, 0, 0);
    const link = document.createElement('a');
    link.download = 'result1.png';
    link.href = outputCanvas.toDataURL('image/png');
    link.click();
    const outputCanvas2 = document.createElement('canvas');
    outputCanvas2.width = size * 4;
    outputCanvas2.height = size * 3;
    const ctx2 = outputCanvas2.getContext('2d');
    for (const dir of directions){
        const face = faceMap[dir.name];
        if (dir.name == "px") {
            const imageData = face.getContext('2d').getImageData(0, 0, size, size);
            ctx2.putImageData(imageData, size * 1.5, size);
        } else if (dir.name == "py") {
            const imageData = face.getContext('2d').getImageData(0, 0, size, size);
            ctx2.putImageData(imageData, size * 1.5, 0);
        } else if (dir.name == "pz") {
            const imageData = face.getContext('2d').getImageData(0, 0, size, size);
            ctx2.putImageData(imageData, size * 1.5 + size, size);
        } else if (dir.name == "nz") {
            const imageData = face.getContext('2d').getImageData(0, 0, size, size);
            ctx2.putImageData(imageData, size * 1.5 - size, size);
        } else if (dir.name == "nx") {
            const imageData = face.getContext('2d').getImageData(0, 0, size, size);
            ctx2.putImageData(imageData, size * 1.5 - size * 2, size);
            ctx2.putImageData(imageData, size * 1.5 + size * 2, size);
        } else {
            const imageData = face.getContext('2d').getImageData(0, 0, size, size);
            ctx2.putImageData(imageData, size * 1.5, size * 2);
        }
    }
    const link2 = document.createElement('a');
    link2.download = 'result2.png';
    link2.href = outputCanvas2.toDataURL('image/png');
    link2.click();
}
function downloadComposerOutput() {
    const gl = renderer.getContext();
    // 画像サイズを取得
    const width = renderer.domElement.width;
    const height = renderer.domElement.height;
    // ピクセルデータを格納するための配列
    const pixels = new Uint8Array(width * height * 4); // RGBA
    // レンダーターゲットを指定
    const framebuffer = gl.createFramebuffer();
    gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
    composer.render();
    gl.readPixels(0, 0, width, height, gl.RGBA, gl.UNSIGNED_BYTE, pixels);
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d');
    // imageData を作成して読み取ったピクセルデータを設定
    const imageData = ctx.createImageData(width, height);
    // ピクセルを上下反転してコピー
    for(let y = 0; y < height; y++)for(let x = 0; x < width; x++){
        const destIdx = (y * width + x) * 4;
        const srcIdx = ((height - y - 1) * width + x) * 4;
        imageData.data[destIdx] = pixels[srcIdx];
        imageData.data[destIdx + 1] = pixels[srcIdx + 1];
        imageData.data[destIdx + 2] = pixels[srcIdx + 2];
        imageData.data[destIdx + 3] = 255; // pixels[srcIdx + 3]; 透明度
    }
    ctx.putImageData(imageData, 0, 0);
    // ダウンロードリンク作成
    const link = document.createElement('a');
    link.download = 'output.png';
    link.href = canvas.toDataURL('image/png');
    link.click();
}
