//等級と大きさの変換
function vmagToSize(vmag) {
    const minSize = 0.1;
    const maxSize = 42.25;
    return Math.max(minSize, maxSize - vmag * 6.5);
}
//B-V色指数から色温度(K)へ変換
function bv2Temperature(bv) {
    return 4600 * (1 / (0.92 * bv + 1.7) + 1 / (0.92 * bv + 0.62));
}
//CIE xy 色度図なるものを用いて色空間の座標を求めるらしい
function temperatureToXYZ(tempK) {
    let x, y;
    if (tempK >= 1667 && tempK <= 4000) x = -0.2661239 * 1e9 / tempK ** 3 - 234358 / tempK ** 2 + 877.6956 / tempK + 0.179910;
    else if (tempK > 4000 && tempK <= 25000) x = -3025846900 / tempK ** 3 + 2107037.9 / tempK ** 2 + 0.2226347 * 1e3 / tempK + 0.240390;
    else x = 0.31271;
    y = -3 * x ** 2 + 2.870 * x - 0.275;
    const Y = 1.0;
    const X = Y / y * x;
    const Z = Y / y * (1 - x - y);
    return [
        X,
        Y,
        Z
    ];
}
//座標からRGBに変換するらしい
function xyzToRgb([X, Y, Z]) {
    let r = 3.2406 * X - 1.5372 * Y - 0.4986 * Z;
    let g = -0.9689 * X + 1.8758 * Y + 0.0415 * Z;
    let b = 0.0557 * X - 0.2040 * Y + 1.0570 * Z;
    // clamp
    return [
        Math.max(0, Math.min(1, r)),
        Math.max(0, Math.min(1, g)),
        Math.max(0, Math.min(1, b))
    ];
}
//彩度の補正
function boostColor([r, g, b], factor = 2) {
    const avg = (r + g + b) / 3;
    r = avg + (r - avg) * factor * 1.8;
    g = avg + (g - avg) * factor * 0.2;
    b = avg + (b - avg) * factor * 0.2;
    return [
        Math.max(0, Math.min(1, r)),
        Math.max(0, Math.min(1, g)),
        Math.max(0, Math.min(1, b))
    ];
}
//まとめたもの
function bvToRgb(bv) {
    const temp = bv2Temperature(bv);
    const xyz = temperatureToXYZ(temp);
    return boostColor(xyzToRgb(xyz));
}
// ユリウス日を求める関数（UTC基準）
function getJulianDate(year, month, day, hour, min, sec) {
    /* const year = date.getUTCFullYear();
    const month = date.getUTCMonth() + 1;
    const day = date.getUTCDate();
    const hour = date.getUTCHours();
    const min = date.getUTCMinutes();
    const sec = date.getUTCSeconds(); */ const targetDate = Date.UTC(year, month - 1, day, hour, min, sec);
    const baseDate = Date.UTC(2000, 0, 1, 12);
    const baseJD = 2451545.0; // 2000-01-01 12:00 UT
    const msPerDay = 86400000;
    const JD = baseJD + (targetDate - baseDate) / msPerDay;
    //console.log(JD)
    return JD;
}
//LST(地方恒星時を計算)
function getLST(year, month, day, hour, min, sec, longitudeDeg) {
    // 1. 日付をUTCで取得
    const JD = getJulianDate(year, month, day, hour, min, sec); // ユリウス日（UTC）
    const D = JD - 2451545.0; // J2000.0 からの経過日数
    // GSTの計算(度)
    let GST = 280.46061837 + D * 360.9856476; //280.46...が、J2000.0でのGST(らしい)
    //let GST = 24 * (0.671262 + 1.00273791 * (JD-2440000.5))*15;//1太陽日＝1.00273791恒星日(理科年表より)
    //console.log((GST % 360 + 360) % 360);
    // 経度を足してLSTに変換（東経はプラス、西経はマイナス）
    let LST = GST + longitudeDeg;
    // 0〜360度に正規化
    LST = (LST % 360 + 360) % 360;
    return LST;
}
