Promise.all([
    fetch((0, _starTableJsonUrlDefault.default)).then((res)=>res.json()),
    fetch((0, _indexJsonUrlDefault.default)).then((res)=>res.json())
]).then(([stars, constellations])=>{
    stars_data = stars;
    constellations_data = constellations;
    const geometry = new _three.BufferGeometry();
    const positions = [];
    const colors = [];
    const sizes = [];
    const intensities = [];
    const color = new _three.Color();
    const simulatedDate = getSimulatedDate();
    let year = simulatedDate.getFullYear();
    let month = simulatedDate.getMonth() + 1;
    let day = simulatedDate.getDate();
    let hour = simulatedDate.getHours();
    let min = simulatedDate.getMinutes();
    let sec = simulatedDate.getSeconds();
    // 日本時間（例：2025年1月1日 23:00）
    const jst = new Date(year, month, day, hour, min, sec);
    // UTCに変換
    const utc = new Date(jst.getTime() - 32400000); // -9時間
    year = utc.getUTCFullYear();
    month = utc.getUTCMonth() + 1;
    day = utc.getUTCDate();
    hour = utc.getUTCHours();
    min = utc.getUTCMinutes();
    sec = utc.getUTCSeconds();
    //console.log(getLST(year,month,day,hour,min,sec,139.75));
    const LST_Deg = getLST(year, month, day, hour, min, sec, longitude);
    const LST_Rad = LST_Deg * Math.PI / 180;
    const lat_Deg = latitude; //観測点の緯度(北緯)
    const lat_Rad = lat_Deg * Math.PI / 180;
    const year_JD = getJulianDate(year, month, day, hour, min, sec);
    //const delta_RA_deg = (360 / 25772) * (year_JD - 2451545.0)/365.25;
    //console.log(delta_RA_deg);
    stars.forEach((star)=>{
        const raw_RA_Deg = star.ra_deg; //RA(度数法)(春分点の赤経からの距離)(J.2000.0)
        const RA_Deg = raw_RA_Deg // + delta_RA_deg;
        ;
        const DEC_Deg = star.dec_deg; //DEC(度数法)(天の赤道からの距離)
        //ラジアンに変換
        let RA_Rad = RA_Deg * Math.PI / 180;
        let DEC_Rad = DEC_Deg * Math.PI / 180;
        let raDec = {
            ra: RA_Rad,
            dec: DEC_Rad
        };
        let newRaDec = (0, _astronomia.precess).position(raDec, 2000, year, 0, 0); //歳差運動による誤差まで自力で求めたかったが力及ばず...無念...
        RA_Rad = newRaDec.ra;
        DEC_Rad = newRaDec.dec;
        //観測点からの高さを求める
        const HA_Rad = LST_Rad - RA_Rad;
        const sinAlt = Math.sin(DEC_Rad) * Math.sin(lat_Rad) + Math.cos(DEC_Rad) * Math.cos(lat_Rad) * Math.cos(HA_Rad);
        const Alt_Rad = Math.asin(sinAlt);
        //観測点からの左右の角度を求める
        const cosAz = (Math.sin(DEC_Rad) - Math.sin(Alt_Rad) * Math.sin(lat_Rad)) / (Math.cos(Alt_Rad) * Math.cos(lat_Rad));
        const sinAz = -Math.cos(DEC_Rad) * Math.sin(HA_Rad) / Math.cos(Alt_Rad);
        let Az_Rad = Math.atan2(sinAz, cosAz);
        const star_x = starDistance * Math.cos(Alt_Rad) * Math.cos(Az_Rad);
        const star_y = starDistance * Math.sin(Alt_Rad);
        const star_z = starDistance * Math.cos(Alt_Rad) * Math.sin(Az_Rad);
        //見かけの等級
        const vmag = star.vmag;
        positions.push(star_x, star_y, star_z);
        hipPosition[star.hip_number] = new _three.Vector3(star_x, star_y, star_z);
        hipNumbers.push(star.hip_number);
        const star_intensity = Math.max(1.1 - star.vmag / 6.5, 0.0) + 9;
        //color.setRGB(star_intensity, star_intensity, star_intensity);
        intensities.push(star_intensity);
        const sRGB = bvToRgb(star.bv_color);
        color.setRGB(sRGB[0], sRGB[1], sRGB[2]);
        colors.push(color.r, color.g, color.b);
        const size = vmagToSize(vmag);
        sizes.push(size);
    //console.log(size);
    });
    geometry.setAttribute('position', new _three.Float32BufferAttribute(positions, 3));
    geometry.setAttribute('customColor', new _three.Float32BufferAttribute(colors, 3));
    geometry.setAttribute('size', new _three.Float32BufferAttribute(sizes, 1));
    geometry.setAttribute('intensity', new _three.Float32BufferAttribute(intensities, 1));
    geometry.setAttribute('hipNumbers', new _three.Float32BufferAttribute(hipNumbers, 1));
    star_geometry = geometry;
    const star_img = "data:image/png;base64,";
    //ありがとうChatGPT
    star_material = new _three.ShaderMaterial({
        uniforms: {
            time: {
                value: 0.0
            },
            pointTexture: {
                value: new _three.TextureLoader().load(star_img)
            } //円形の画像データ
        },
        vertexShader: `
            attribute float intensity;
            attribute float size;
            attribute vec3 customColor;
            attribute float hipNumbers;
            varying vec3 vColor;
            varying float vIntensity;
            varying float vRandom;
        
            void main() {
                vRandom = fract(sin(hipNumbers) * 43758.5453);
                vColor = customColor;
                vIntensity = intensity;
                vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
                gl_PointSize = size * (300.0 / -mvPosition.z); // \u{9060}\u{8FD1}\u{6CD5}\u{88DC}\u{6B63}
                //gl_PointSize = size;
                gl_Position = projectionMatrix * mvPosition;
            }
        `,
        fragmentShader: `
            uniform sampler2D pointTexture;
            uniform float time;
            varying vec3 vColor;
            varying float vIntensity;
            varying float vRandom;
        
            void main() {
                float speed = 1.0 + vRandom * 2.0; 
                float flicker = 0.6 + 0.4 * sin(time * speed + vRandom * 6.28);
                vec4 texColor = texture2D(pointTexture, gl_PointCoord);
                vec3 finalColor = vColor * vIntensity * flicker;
                gl_FragColor = vec4(finalColor, 1.0) * texColor;
            }
        `,
        transparent: true,
        depthWrite: false,
        sizeAttenuation: false,
        vertexColors: true
    });
    const points = new _three.Points(geometry, star_material);
    star_points = points;
    scene.add(points);
    const line_colors = [
        0x1df8de,
        0xd74443,
        0x70aeff,
        0xe0e34c,
        0xf89d1d,
        0xeccbdc
    ];
    constellations.constellations.forEach((constellation)=>{
        let line_color = line_colors[Math.floor(Math.random() * line_colors.length)];
        constellation.lines.forEach((line)=>{
            let error_count = 0;
            //console.log(line)
            const linePositions = [];
            //if(constellation.common_name.native=="Cassiopeia"){
            for(let i = 0; i < line.length - 1; i++){
                const hip1 = line[i];
                const hip2 = line[i + 1];
                if (!constellations_stars[hip1]) constellations_stars[hip1] = [];
                if (!constellations_stars[hip2]) constellations_stars[hip2] = [];
                if (!constellations_stars[hip1].includes(constellation.common_name.native)) constellations_stars[hip1].push(constellation.common_name.native);
                if (!constellations_stars[hip2].includes(constellation.common_name.native)) constellations_stars[hip2].push(constellation.common_name.native);
                const pos1 = hipPosition[hip1];
                const pos2 = hipPosition[hip2];
                if (pos1 && pos2) {
                    linePositions.push(pos1.x, pos1.y, pos1.z);
                    linePositions.push(pos2.x, pos2.y, pos2.z);
                } else {
                    console.log(hip1);
                    console.log(hip2);
                    error_count++;
                }
            }
            //}
            const lineGeometry = new _three.BufferGeometry();
            lineGeometry.setAttribute('position', new _three.Float32BufferAttribute(linePositions, 3));
            const lineMaterial = new _three.LineBasicMaterial({
                color: line_color,
                transparent: true,
                opacity: 0.7,
                depthWrite: false,
                depthTest: true
            });
            const lineMesh = new _three.LineSegments(lineGeometry, lineMaterial);
            line_geometorlies.push(lineGeometry);
            if (error_count == 0) {
                scene.add(lineMesh);
                constellation_lines.push(lineMesh);
            }
        });
    });
    //console.log("1:",error_count);
    update_star();
//get_6dir_img();
});
