function createTextSprite(text, RGB, bright, size) {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', {
        alpha: true
    });
    // Canvas サイズ
    canvas.width = 512 * text.length;
    canvas.height = 512;
    // 背景は透明
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    //console.log(RGB);
    ctx.fillStyle = `rgb(${RGB.r * 255},${RGB.g * 255},${RGB.b * 255})`;
    // スタイル設定
    ctx.font = '512px nikokaku';
    //ctx.fillStyle = 'white';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    // テキスト描画
    ctx.fillText(text, canvas.width / 2, canvas.height / 2);
    // Canvas からテクスチャを作成
    const texture = new _three.CanvasTexture(canvas);
    const material = new _three.SpriteMaterial({
        map: texture,
        transparent: true,
        opacity: 0,
        alphaTest: 0.1
    });
    const sprite = new _three.Sprite(material);
    // スケール調整（大きさ）
    sprite.scale.set(size * text.length * 0.01, size * 0.01, 1); // 横:縦の比率をCanvasと合わせると綺麗
    return {
        sprite,
        radius: text.length * size,
        texture: texture,
        material: material
    };
}
function get_lookat_pos(dis = 40) {
    const dir = new _three.Vector3();
    camera.getWorldDirection(dir);
    dir.multiplyScalar(dis);
    const pos = camera.position.clone().add(dir);
    return pos;
}
function sphericalToCartesian(radius, latitude, longitude) {
    // 緯度(latitude)・経度(longitude) はラジアンで
    const x = radius * Math.cos(latitude) * Math.cos(longitude);
    const y = radius * Math.sin(latitude);
    const z = radius * Math.cos(latitude) * Math.sin(longitude);
    return new _three.Vector3(x, y, z);
}
