function placeTextSprite(text, bv, bright, size) {
    //console.log(bv);
    const color_rgb = bvToRgb(bv);
    const color = new _three.Color();
    color.setRGB(color_rgb[0], color_rgb[1], color_rgb[2]);
    const { sprite, radius, texture, material } = createTextSprite(text, color, bright, size);
    let basePos = get_lookat_pos(40);
    const dir = new _three.Vector3(0, 0, -1);
    dir.applyQuaternion(camera.quaternion);
    dir.normalize();
    const baseLat = Math.asin(dir.y) / Math.PI * 180;
    const baseLng = Math.atan2(dir.z, dir.x) / Math.PI * 180;
    let placed = false;
    let final_lat;
    let final_lng;
    let corrected_pos;
    //corrected_pos = basePos;
    for(let i = 0; i < 100; i++){
        let safe = true;
        const angle = Math.random() * 2 * Math.PI;
        const r = 0.12 * i * size;
        const latOffset = Math.sin(angle) * r;
        const lngOffset = Math.cos(angle) * r;
        //const latOffset = Math.sign((Math.random()) - 0.5) * 0.06*i; // 調整可
        //const lngOffset = Math.sign((Math.random()) - 0.5) * 0.06*i;
        const lat = (baseLat + latOffset) * Math.PI / 180;
        const lng = (baseLng + lngOffset) * Math.PI / 180;
        final_lat = lat;
        final_lng = lng;
        corrected_pos = sphericalToCartesian(40, lat, lng);
        //corrected_pos = basePos.clone().add(offset);
        for (let other of existingSprites){
            const minDist = radius + other.radius;
            //console.log(minDist);
            //console.log(corrected_pos.distanceTo(other.sprite.position));
            if (corrected_pos.distanceTo(other.sprite.position) < minDist / 3) {
                console.log("\u8FD1\u3059\u304E");
                safe = false;
                break;
            }
        }
        if (safe) {
            sprite.position.copy(corrected_pos);
            existingSprites.push({
                sprite: sprite,
                radius: radius,
                texture: texture,
                material: material
            });
            scene.add(sprite);
            placed = true;
            break;
        }
    }
    if (!placed) {
        final_lat = baseLat;
        final_lng = baseLng;
        sprite.position.copy(basePos);
        existingSprites.push({
            sprite: sprite,
            radius: radius,
            texture: texture,
            material: material
        });
        scene.add(sprite);
    //console.log("failed");
    }
    let tl = (0, _gsap.gsap).timeline();
    sprite.material.rotation = 0;
    tl.to(sprite.material, {
        rotation: Math.PI * 2,
        duration: 0.2
    }, 0);
    tl.to(sprite.scale, {
        x: size * text.length,
        y: size,
        duration: 0.2,
        ease: "power3.inOut"
    }, 0);
    tl.to(sprite.material, {
        opacity: bright,
        duration: 1
    }, 0);
    //短冊が近くにあったら処理
    const pos = sprite.position;
    triggerExplosion(pos, final_lat, final_lng);
    tanzaku_list.forEach((tanzaku)=>{
        const dis = pos.distanceTo(tanzaku.mesh.position);
        //console.log(dis);
        if (radius / 3 * 2 >= dis) //scene.remove(tanzaku);
        {
            if (!tanzaku.isAnimating) {
                num_found_tanzaku++;
                if (num_found_tanzaku >= 27) found_tanzaku.style.color = "red";
                get_tanzaku_animation(tanzaku.mesh, tanzaku.imgURL, tanzaku.users);
                tanzaku.isAnimating = true;
            }
        }
    });
    //ここで線を描画
    const len = existingSprites.length;
    if (len >= 2) {
        let linePositions = [];
        const pos1 = existingSprites[len - 2].sprite.position;
        const pos2 = existingSprites[len - 1].sprite.position;
        //console.log(pos1);
        //console.log(pos2);
        linePositions.push(pos1.x, pos1.y, pos1.z, pos2.x, pos2.y, pos2.z);
        const lineGeometry = new _three.BufferGeometry();
        lineGeometry.setAttribute('position', new _three.Float32BufferAttribute(linePositions, 3));
        let line_color;
        //console.log(current_line_color_mode);
        if (current_line_color_mode == 1) line_color = line_colors[0];
        else if (current_line_color_mode == 2) line_color = line_colors[4];
        else if (current_line_color_mode == 3) line_color = line_colors[3];
        else if (current_line_color_mode == 4) line_color = line_colors[5];
        else if (current_line_color_mode == 5) line_color = line_colors[1];
        else if (current_line_color_mode == 6) line_color = line_colors[2];
        else line_color = line_colors[Math.floor(Math.random() * line_colors.length)];
        const lineMaterial = new _three.LineBasicMaterial({
            color: line_color,
            transparent: true,
            depthWrite: false,
            depthTest: true,
            opacity: 0.5
        });
        lineMaterial.color.multiplyScalar(50);
        const lineMesh = new _three.Line(lineGeometry, lineMaterial);
        scene.add(lineMesh);
        starlines.push(lineMesh);
    }
}
let particle_list = [];
const star_texture = textureLoader.load((0, _starPngDefault.default));
class ParticleExplosion {
    constructor(position, scene, num_found_tanzaku, lat, lng, count = 20, lifetime = 0.5){
        this.scene = scene;
        this.lifetime = lifetime;
        this.elapsed = 0;
        this.count = count;
        this.clear_border = 27;
        this.num_found_tanzaku = num_found_tanzaku;
        if (num_found_tanzaku >= this.clear_border) {
            this.color = line_colors[Math.floor(Math.random() * line_colors.length)];
            this.count = 60;
            this.lifetime = 0.5;
            const normal = new _three.Vector3(position.x, position.y, position.z).normalize(); //(0,0,0)から目標座標への単位ベクトル
            const temp = new _three.Vector3(0, 1, 0);
            if (Math.abs(normal.dot(temp)) > 0.99) temp.set(1, 0, 0); // ほぼ平行な場合は別の軸を使う
            this.axis1 = new _three.Vector3().crossVectors(normal, temp).normalize();
            this.axis2 = new _three.Vector3().crossVectors(normal, this.axis1).normalize();
        } else this.color = 0xffffaa;
        this.geometry = new _three.BufferGeometry();
        this.positions = new Float32Array(this.count * 3);
        this.velocities = [];
        for(let i = 0; i < this.count; i++){
            this.positions[i * 3] = position.x;
            this.positions[i * 3 + 1] = position.y;
            this.positions[i * 3 + 2] = position.z;
            let dir;
            if (num_found_tanzaku < this.clear_border) dir = new _three.Vector3((Math.random() - 0.5) * 0.05, (Math.random() - 0.5) * 0.05, (Math.random() - 0.5) * 0.05);
            else {
                if (i < 20) {
                    const angle = Math.PI * 2 / 20 * i;
                    const direction = new _three.Vector3().addScaledVector(this.axis1, Math.cos(angle)).addScaledVector(this.axis2, Math.sin(angle));
                    dir = direction.clone().multiplyScalar(0.06);
                } else if (20 <= i && i < 40) {
                    const angle = Math.PI * 2 / 20 * (i - 20);
                    const direction = new _three.Vector3().addScaledVector(this.axis1, Math.cos(angle)).addScaledVector(this.axis2, Math.sin(angle));
                    dir = direction.clone().multiplyScalar(0.12);
                } else {
                    const angle = Math.PI * 2 / 20 * (i - 40);
                    const direction = new _three.Vector3().addScaledVector(this.axis1, Math.cos(angle)).addScaledVector(this.axis2, Math.sin(angle));
                    dir = direction.clone().multiplyScalar(0.09);
                }
            }
            this.velocities.push(dir);
        }
        this.geometry.setAttribute('position', new _three.BufferAttribute(this.positions, 3));
        this.material = new _three.PointsMaterial({
            map: star_texture,
            size: 2,
            color: this.color,
            transparent: true,
            opacity: 0.5,
            depthWrite: false,
            alphaTest: 0.1
        });
        this.points = new _three.Points(this.geometry, this.material);
        this.scene.add(this.points);
        particle_list.push(this.points);
    }
    update(delta) {
        this.elapsed += delta;
        for(let i = 0; i < this.velocities.length; i++){
            this.positions[i * 3] += this.velocities[i].x;
            this.positions[i * 3 + 1] += this.velocities[i].y - 0.06 * this.elapsed;
            this.positions[i * 3 + 2] += this.velocities[i].z;
        }
        if (this.num_found_tanzaku < this.clear_border) this.material.opacity = Math.max(3 - 3 * this.elapsed / this.lifetime, 0);
        else if (this.elapsed / this.lifetime < 0.5) this.material.opacity = Math.min(10 * this.elapsed / this.lifetime * 2, 10);
        else this.material.opacity = Math.max(5 - 5 * this.elapsed / this.lifetime - 1, 0);
        this.geometry.attributes.position.needsUpdate = true;
    }
    isDead() {
        return this.elapsed >= this.lifetime;
    }
    dispose() {
        this.points.visible = false;
        this.scene.remove(this.points);
        this.geometry.dispose();
        this.material.dispose();
    }
}
