function drawImageRotated(ctx, img, x, y, options = {}) {
    const { rotation = 0, scale = 1.0, opacity = 1.0, width = img.width, height = img.height, filter = null } = options;
    ctx.save(); // 現在の状態を保存
    ctx.globalAlpha = opacity;
    if (filter) ctx.filter = filter;
    ctx.translate(x, y);
    ctx.rotate(rotation);
    ctx.scale(scale, scale);
    ctx.drawImage(img, -width / 2, -height / 2, width, height);
    ctx.restore(); // 状態を元に戻す
}
const tanzaku_back_ims = button_back_imgs.concat([
    (0, _milkywayPngDefault.default)
]);
