function make_tanzaku_and_place(dis = 40, quantity_per_one = 6) {
    original_tanzaku_list = [];
    tanzaku_list = [];
    tanzaku_imgs.forEach((tanzaku)=>{
        const img = new Image();
        img.src = tanzaku;
        img.onload = async ()=>{
            for(let i = 0; i < quantity_per_one; i++){
                const canvas = document.createElement('canvas');
                const ctx = canvas.getContext('2d');
                canvas.width = img.height;
                canvas.height = img.width;
                ctx.save();
                ctx.translate(canvas.width / 2, canvas.height / 2);
                ctx.rotate(90 * Math.PI / 180);
                ctx.drawImage(img, -img.width / 2, -img.height / 2);
                ctx.restore();
                const promises = [];
                for(let k = 0; k < 5; k++){
                    const img_src = tanzaku_back_ims[Math.floor(Math.random() * tanzaku_back_ims.length)];
                    const p = new Promise((resolve)=>{
                        const back_img = new Image();
                        back_img.src = img_src;
                        back_img.onload = ()=>{
                            resolve(back_img); // 読み込み完了したら渡す
                        };
                    });
                    promises.push(p);
                }
                const loaded_images = await Promise.all(promises); // 全部ロード完了を待つ
                loaded_images.forEach((back_img)=>{
                    const x = Math.random() * ctx.canvas.width;
                    const y = Math.max(Math.random(), 0.3) * ctx.canvas.height;
                    //console.log(x,y);
                    drawImageRotated(ctx, back_img, x, y, {
                        rotation: Math.random() * Math.PI * 2,
                        scale: 0.5 + Math.random() * 1.0,
                        opacity: 0.4 + Math.random() * 0.5,
                        filter: 'blur(6px)'
                    });
                });
                const dataUrl = canvas.toDataURL();
                const texture = new _three.CanvasTexture(canvas);
                const material = new _three.MeshBasicMaterial({
                    map: texture,
                    transparent: true,
                    opacity: 0.4,
                    alphaTest: 0.1,
                    side: _three.DoubleSide
                });
                const geometry = new _three.PlaneGeometry(0.4, 2.0);
                const tanzaku_mesh = new _three.Mesh(geometry, material);
                //tanzaku_mesh.position.set(Math.random()*10-5,2,Math.random()*10-5);
                const theta = Math.random() * Math.PI * 2; //短冊の緯度
                const phi = Math.asin(2 * Math.random() - 1); //短冊の経度//直接高さの角度を決めると偏るのでasinで逆算
                const x = dis * Math.cos(phi) * Math.cos(theta);
                const y = dis * Math.sin(phi);
                const z = dis * Math.cos(phi) * Math.sin(theta);
                tanzaku_mesh.position.set(x, y, z);
                tanzaku_mesh.lookAt(0, 0, 0);
                if (i < quantity_per_one - 1) {
                    scene.add(tanzaku_mesh);
                    tanzaku_list.push({
                        mesh: tanzaku_mesh,
                        isAnimating: false,
                        imgURL: dataUrl,
                        users: false,
                        geometry: geometry,
                        material: material,
                        texture: texture
                    });
                } else original_tanzaku_list.push({
                    mesh: tanzaku_mesh,
                    imgURL: dataUrl,
                    URL4css: tanzaku,
                    geometry: geometry,
                    material: material,
                    texture: texture
                });
            }
        };
    });
}
