//ありがとうchatgpt(n度目)
function loadImages(srcArray) {
    return Promise.all(srcArray.map((src)=>{
        return new Promise((resolve, reject)=>{
            const img = new Image();
            img.onload = ()=>resolve(img);
            img.onerror = reject;
            img.src = src;
        });
    }));
}
let galazy_star_geometory;
let galazy_star_material;
let arms_data = [];
const zRotation = -Math.PI / 4;
let current_galaxy_rotate = 0;
let cloudsprite;
let cloudtexture;
let cloudmaterial;
let galaxy_star_points;
function create_galaxy() {
    arms_data = [];
    const count = 14400;
    const r_base = 400;
    const radiusStep = r_base / count;
    const angleStep = Math.PI * 2 / count * 0.8;
    let positions = [];
    const arms = 5;
    const geometry = new _three.BufferGeometry();
    const center = new _three.Vector3(1200, 1200, 0);
    const color_list = [
        0xbb99bb,
        0xbb9999,
        0x99bbbb,
        0xbb99aa,
        0x99bbdd,
        0xff6688,
        0x66ff88,
        0xff9966
    ];
    const color = new _three.Color();
    let colors = [];
    for(let j = 0; j < arms; j++){
        const armOffset = Math.PI * 2 / arms * j;
        for(let i = 0; i < count; i++){
            const r = i * radiusStep;
            const theta = i * angleStep + armOffset;
            const spread_range = random_spread(i, 70, count);
            let armz = r * Math.cos(theta) + (Math.random() - 0.5) * spread_range;
            let army = r * Math.sin(theta) + (Math.random() - 0.5) * spread_range;
            let armx = (Math.random() - 0.5) * spread_range; // 少し厚みを持たせる
            const rotatedX = army * Math.cos(zRotation);
            const rotatedY = army * Math.sin(zRotation);
            arms_data.push([
                armx,
                army,
                armz,
                center.clone()
            ]);
            armx = rotatedX + center.x + armx;
            army = rotatedY + center.y;
            armz = armz + center.z;
            positions.push(armx, army, armz);
            if (i > count * 0.5) color.setHex(0x9999bb);
            else if (i <= count * 0.5 && i >= count * 0.05) color.setHex(color_list[Math.floor(Math.random() * color_list.length)]);
            else color.setHex(0xaaaaaa);
            colors.push(color.r, color.g, color.b);
        }
    }
    //console.log(colors);
    geometry.setAttribute("position", new _three.Float32BufferAttribute(positions, 3));
    geometry.setAttribute("color", new _three.Float32BufferAttribute(colors, 3));
    galazy_star_geometory = geometry;
    const material = new _three.PointsMaterial({
        size: 7,
        vertexColors: true,
        /* color: 0xbb99aa, */ transparent: true,
        opacity: 3,
        depthWrite: false,
        /* map: texture, */ alphaTest: 0.001,
        blending: _three.AdditiveBlending
    });
    galazy_star_material = material;
    const points = new _three.Points(geometry, material);
    galaxy_star_points = points;
    scene.add(points);
    loadImages(clouds).then((images)=>{
        const canvas = document.createElement('canvas');
        canvas.width = 800;
        canvas.height = 800;
        const ctx = canvas.getContext('2d');
        let weights = [];
        for(let i = 0; i < images.length - 1; i++){
            let total = weights.reduce((sum, element)=>sum + element, 0);
            weights.push(Math.random() * (1 - total));
        }
        let total = weights.reduce((sum, element)=>sum + element, 0);
        weights.push(1 - total);
        images.forEach((img, i)=>{
            //console.log(weights[i]);
            ctx.globalAlpha = weights[i];
            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        });
        // CanvasからThree.js用のテクスチャに
        cloudtexture = new _three.CanvasTexture(canvas);
        //document.body.appendChild(canvas);
        cloudmaterial = new _three.SpriteMaterial({
            map: cloudtexture,
            transparent: true,
            depthWrite: false,
            opacity: 0.5,
            color: 0x11ffff
        });
        cloudsprite = new _three.Sprite(cloudmaterial);
        cloudsprite.scale.set(1000, 1000, 1);
        cloudsprite.position.set(800, 800, 0);
        scene.add(cloudsprite);
        cloudsprite.lookAt(0, 0, 0);
    });
}
//create_galaxy();
const total_addition_angle = -Math.PI * 2;
const GalaxyRotate_duration = 5000;
let GalaxyRotateStart_time = undefined;
let GalaxyRotating = false;
let rotate_progress = 0;
let center_goal2 = new _three.Vector3(50, 50, 0);
function rotate_galaxyStars() {
    let addition_angle = 0;
    if (GalaxyRotating) {
        if (GalaxyRotateStart_time == undefined) GalaxyRotateStart_time = performance.now();
        const now = performance.now();
        const galaxystar_positions = galazy_star_geometory.attributes.position.array;
        const past_time_ms = now - GalaxyRotateStart_time;
        rotate_progress = past_time_ms / GalaxyRotate_duration;
        if (rotate_progress >= 1) {
            rotate_progress = 0;
            GalaxyRotateStart_time = undefined;
            GalaxyRotating = false;
            return;
        }
        const eased_progress = easeInOutCubic(rotate_progress);
        addition_angle = total_addition_angle * eased_progress + current_galaxy_rotate;
        let index = 0;
        arms_data.forEach((arms)=>{
            let armx = arms[0];
            let army = arms[1];
            let armz = arms[2];
            let center = arms[3];
            let radius = Math.sqrt(army ** 2 + armz ** 2);
            const angleRad = Math.atan2(army, armz);
            const updated_angleRad = angleRad + addition_angle;
            army = radius * Math.sin(updated_angleRad);
            armz = radius * Math.cos(updated_angleRad);
            const rotatedX = army * Math.cos(zRotation);
            const rotatedY = army * Math.sin(zRotation);
            center = new _three.Vector3().lerpVectors(center, center_goal2, eased_progress);
            armx = rotatedX + center.x + armx;
            army = rotatedY + center.y;
            armz = armz + center.z;
            //arms[3] = center;
            galaxystar_positions[index * 3] = armx;
            galaxystar_positions[1 + index * 3] = army;
            galaxystar_positions[2 + index * 3] = armz;
            index++;
        });
        if (cloudsprite && cloudsprite.material) cloudsprite.material.rotation = -addition_angle;
        galazy_star_geometory.attributes.position.needsUpdate = true;
    } else if (GalaxyRotateStart_time !== undefined) current_galaxy_rotate = addition_angle;
}
let always_GalaxyRotating = false;
let rotation_pase = 5;
let addition_angle = 0;
function always_rotate_galaxyStars() {
    if (always_GalaxyRotating) {
        if (GalaxyRotateStart_time == undefined) GalaxyRotateStart_time = performance.now();
        const now = performance.now();
        const galaxystar_positions = galazy_star_geometory.attributes.position.array;
        const past_time_ms = now - GalaxyRotateStart_time;
        const progress = past_time_ms % (GalaxyRotate_duration * rotation_pase) / (GalaxyRotate_duration * rotation_pase);
        addition_angle = total_addition_angle * progress;
        let index = 0;
        arms_data.forEach((arms)=>{
            let armx = arms[0];
            let army = arms[1];
            let armz = arms[2];
            let center = arms[3];
            let radius = Math.sqrt(army ** 2 + armz ** 2);
            const angleRad = Math.atan2(army, armz);
            const updated_angleRad = angleRad + addition_angle + current_galaxy_rotate;
            army = radius * Math.sin(updated_angleRad);
            armz = radius * Math.cos(updated_angleRad);
            const rotatedX = army * Math.cos(zRotation);
            const rotatedY = army * Math.sin(zRotation);
            armx = rotatedX + center.x + armx;
            army = rotatedY + center.y;
            armz = armz + center.z;
            galaxystar_positions[index * 3] = armx;
            galaxystar_positions[1 + index * 3] = army;
            galaxystar_positions[2 + index * 3] = armz;
            index++;
        });
        if (cloudsprite && cloudsprite.material) cloudsprite.material.rotation = -addition_angle;
        galazy_star_geometory.attributes.position.needsUpdate = true;
    } else if (GalaxyRotateStart_time !== undefined) current_galaxy_rotate = addition_angle;
}
